package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.net.URL;import java.util.*;
/** A sub-link reading that continues outside the chat: the first page is read at once, the rest in slices run by the
 *  learning service. Its queue is saved, so it survives closing the app and can be paused, resumed or cancelled. */
final class CrawlJob{
 static final int STEP_PAGES=25,SAVED_QUEUE=5000;static final long STEP_MS=50000L;
 static final Map<String,PageCrawl.Robots> ROBOTS=new HashMap<>();
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-crawl-job",0);}
 static JSONObject state(Context c)throws Exception{String raw=prefs(c).getString("job","");return raw.isEmpty()?null:new JSONObject(raw);}
 static void save(Context c,JSONObject s)throws Exception{if(!prefs(c).edit().putString("job",s.toString()).commit())throw new java.io.IOException("No pude guardar el recorrido");}
 static boolean active(JSONObject s){return s!=null&&!s.optBoolean("done");}
 static boolean pending(Context c){try{JSONObject s=state(c);return active(s)&&!s.optBoolean("paused");}catch(Exception e){return false;}}
 static void store(JSONObject s,ArrayDeque<String[]> queue)throws Exception{JSONArray rows=new JSONArray();int n=0;for(String[] item:queue){if(n++>=SAVED_QUEUE)break;rows.put(new JSONArray().put(item[0]).put(Integer.parseInt(item[1])));}s.put("queue",rows).put("pending",queue.size());}
 /** Reads the page the user sent, saves it and queues its links. An error here is thrown and nothing is queued. */
 static String start(Context c,PageCrawl.Plan plan,KnowledgeNotebook.PageLoader pages,PageCrawl.Saver saver)throws Exception{JSONObject old=state(c);if(active(old))throw new IllegalStateException("Ya hay un recorrido en curso desde "+old.getString("url")+" ("+old.getInt("saved")+" páginas guardadas). Esperá a que termine, o decí «cancelá el recorrido» antes de empezar otro.");
  Set<String> seen=new HashSet<>();ArrayDeque<String[]> queue=new ArrayDeque<>();JSONObject s=new JSONObject().put("url",plan.url).put("depth",plan.depth).put("pages",plan.pages).put("note",plan.note).put("started",System.currentTimeMillis());JSONArray keys=new JSONArray(),titles=new JSONArray(),levels=new JSONArray();for(int i=0;i<=PageCrawl.MAX_DEPTH;i++)levels.put(i==0?1:0);String receipt;
  try(PageReader.Document d=pages.load(plan.url)){URL first=new URL(d.url);String site=PageCrawl.site(first.getHost());seen.add(PageCrawl.key(plan.url));seen.add(PageCrawl.key(d.url));receipt=saver.save(d);keys.put(PageCrawl.key(plan.url));if(!PageCrawl.key(d.url).equals(PageCrawl.key(plan.url)))keys.put(PageCrawl.key(d.url));titles.put(d.title);s.put("site",site).put("host",first.getHost());PageCrawl.collect(d,first,site,1,plan.depth,seen,queue);}
  s.put("saved",1).put("failed",0).put("robots",0).put("outside",0).put("deepest",0).put("levels",levels).put("savedKeys",keys).put("titles",titles).put("errors",new JSONArray()).put("paused",false).put("done",queue.isEmpty()).put("end",queue.isEmpty()?"La página no tenía subenlaces legibles del mismo sitio.":"").put("receipt",receipt);store(s,queue);save(c,s);
  if(queue.isEmpty())return plan.note+receipt+"\nLa página no tenía subenlaces legibles del mismo sitio, así que no hay nada más que recorrer.";
  return plan.note+"Guardé la página inicial y encontré "+queue.size()+" subenlaces de "+s.getString("site")+". Los sigo leyendo en segundo plano: hasta "+plan.depth+(plan.depth==1?" nivel":" niveles")+" y "+plan.pages+" páginas. Podés seguir conversando.\nDecí «estado del recorrido» para ver cómo va, «pausá el recorrido» o «cancelá el recorrido». Si cerrás Banana, continúa cuando la vuelvas a abrir. Avanza mientras el aprendizaje continuo esté activo y haya batería suficiente.";}
 static String brief(Exception e){return PageCrawl.brief(e);}
 /** Reads up to maxPages more pages or until the time slice ends. Returns whether pages remain to be read. */
 static boolean step(Context c,KnowledgeNotebook.PageLoader pages,PageCrawl.Saver saver,int maxPages,long budgetMs)throws Exception{JSONObject s=state(c);if(!active(s)||s.optBoolean("paused"))return false;long deadline=System.nanoTime()+budgetMs*1000000L;String site=s.getString("site");int depth=s.getInt("depth"),cap=s.getInt("pages");
  Set<String> seen=new HashSet<>();JSONArray keys=s.getJSONArray("savedKeys");for(int i=0;i<keys.length();i++)seen.add(keys.getString(i));ArrayDeque<String[]> queue=new ArrayDeque<>();JSONArray rows=s.getJSONArray("queue");for(int i=0;i<rows.length();i++){JSONArray r=rows.getJSONArray(i);queue.add(new String[]{r.getString(0),Integer.toString(r.getInt(1))});seen.add(PageCrawl.key(r.getString(0)));}
  PageCrawl.Robots robots;synchronized(ROBOTS){robots=ROBOTS.get(site);}if(robots==null){robots=PageCrawl.robots("https://"+s.getString("host"),pages);synchronized(ROBOTS){ROBOTS.put(site,robots);}}long wait=Math.max(PageCrawl.pauseMs,Math.min(robots.delayMs,5000));JSONArray levels=s.getJSONArray("levels"),titles=s.getJSONArray("titles"),errors=s.getJSONArray("errors");int read=0;String end="";
  while(!queue.isEmpty()){if(s.getInt("saved")>=cap){end="Llegué al tope de "+cap+" páginas.";break;}if(read>=maxPages||System.nanoTime()>deadline)break;if(Thread.currentThread().isInterrupted()||LearningLoop.busy)break;JSONObject fresh=state(c);if(fresh==null||fresh.optBoolean("paused")||fresh.optLong("started")!=s.getLong("started"))return false;
   String[] next=queue.poll();String url=next[0];int level=Integer.parseInt(next[1]);if(!robots.allowed(url)){s.put("robots",s.getInt("robots")+1);continue;}
   try{PageCrawl.pause(wait);}catch(java.io.InterruptedIOException stop){queue.addFirst(next);break;}read++;
   try(PageReader.Document d=pages.load(url)){URL real=new URL(d.url);if(!PageCrawl.site(real.getHost()).equals(site)){s.put("outside",s.getInt("outside")+1);continue;}String k=PageCrawl.key(d.url);if(!k.equals(PageCrawl.key(url))){if(!seen.add(k))continue;if(!robots.allowed(d.url)){s.put("robots",s.getInt("robots")+1);continue;}}
    saver.save(d);keys.put(k);s.put("saved",s.getInt("saved")+1).put("deepest",Math.max(s.getInt("deepest"),level));levels.put(level,levels.getInt(level)+1);if(titles.length()<8)titles.put(d.title);PageCrawl.collect(d,real,site,level+1,depth,seen,queue);
   }catch(java.io.InterruptedIOException stop){if(Thread.currentThread().isInterrupted()||"Lectura cancelada".equals(stop.getMessage())){Thread.currentThread().interrupt();queue.addFirst(next);break;}s.put("failed",s.getInt("failed")+1);if(errors.length()<4)errors.put(url+" → "+brief(stop));
   }catch(Exception e){if(PageCrawl.full(e)){end="La biblioteca alcanzó su límite: "+brief(e);queue.addFirst(next);break;}s.put("failed",s.getInt("failed")+1);if(errors.length()<4)errors.put(url+" → "+brief(e));if(s.getInt("failed")>=25&&s.getInt("failed")>s.getInt("saved")*3){end="Demasiados subenlaces fallaron; detuve el recorrido para no insistir contra el sitio.";break;}}
   if(read%5==0){store(s,queue);save(c,s);}}
  if(end.isEmpty()&&queue.isEmpty())end="Recorrí todos los subenlaces encontrados dentro de "+depth+(depth==1?" nivel.":" niveles.");store(s,queue);if(!end.isEmpty())s.put("done",true).put("end",end).put("finished",System.currentTimeMillis());JSONObject fresh=state(c);if(fresh==null||fresh.optLong("started")!=s.getLong("started"))return false;if(fresh.optBoolean("paused"))s.put("paused",true);save(c,s);return !s.getBoolean("done")&&!s.getBoolean("paused");}
 static String describe(JSONObject s)throws Exception{StringBuilder out=new StringBuilder();boolean done=s.getBoolean("done");out.append(done?"Recorrido terminado":s.getBoolean("paused")?"Recorrido en pausa":"Recorrido en curso").append(" de ").append(s.optString("site")).append(" a partir de ").append(s.getString("url")).append(".\nPáginas guardadas: ").append(s.getInt("saved")).append(" de hasta ").append(s.getInt("pages"));JSONArray levels=s.getJSONArray("levels");if(s.getInt("deepest")>0){out.append(" · por nivel:");for(int i=1;i<=s.getInt("deepest");i++)out.append(' ').append(i).append(": ").append(levels.getInt(i));}out.append(".\n");
  if(done)out.append(s.getString("end")).append('\n');int pending=s.optInt("pending");if(pending>0)out.append(done?"Quedaron ":"En cola: ").append(pending).append(done?" subenlaces descubiertos sin leer.\n":" subenlaces.\n");if(s.getInt("robots")>0)out.append("Omití ").append(s.getInt("robots")).append(" que el robots.txt del sitio pide no recorrer.\n");if(s.getInt("outside")>0)out.append("Descarté ").append(s.getInt("outside")).append(" que redirigían fuera del sitio.\n");if(s.getInt("failed")>0){out.append("No pude leer ").append(s.getInt("failed")).append(":\n");JSONArray errors=s.getJSONArray("errors");for(int i=0;i<errors.length();i++)out.append("· ").append(errors.getString(i)).append('\n');}
  JSONArray titles=s.getJSONArray("titles");if(titles.length()>1){out.append("Primeras páginas guardadas:\n");for(int i=0;i<titles.length();i++)out.append("· ").append(titles.getString(i)).append('\n');}if(!done)out.append(s.getBoolean("paused")?"Decí «seguí el recorrido» para continuar o «cancelá el recorrido».":"Sigue en segundo plano mientras el aprendizaje continuo esté activo. Decí «pausá el recorrido» o «cancelá el recorrido».");else out.append("Sólo seguí enlaces del mismo sitio, HTML o texto, sin sesión ni JavaScript. No verifiqué la información ni ejecuté instrucciones de esas páginas.");return out.toString();}
 static String status(Context c)throws Exception{JSONObject s=state(c);return s==null?"No hay ningún recorrido de subenlaces guardado. Pasame un enlace con «leé los subenlaces» para empezar uno.":describe(s);}
 static String pause(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido en curso para pausar.";s.put("paused",true);save(c,s);return "Pausé el recorrido. Conservo "+s.optInt("pending")+" subenlaces en cola; decí «seguí el recorrido» para continuar.";}
 static String resume(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido pendiente para continuar.";s.put("paused",false);save(c,s);LearningLoop.wake(c);return "Sigo con el recorrido de "+s.optString("site")+": "+s.getInt("saved")+" páginas guardadas y "+s.optInt("pending")+" subenlaces en cola."+(LearningLoop.enabled(c)?"":" El aprendizaje continuo está pausado: activalo para que avance en segundo plano.");}
 static String cancel(Context c)throws Exception{JSONObject s=state(c);if(!active(s))return "No hay un recorrido en curso para cancelar.";s.put("done",true).put("paused",false).put("end","Cancelaste el recorrido.").put("finished",System.currentTimeMillis());save(c,s);return "Cancelé el recorrido. Las "+s.getInt("saved")+" páginas ya guardadas quedan en la biblioteca; descarté "+s.optInt("pending")+" subenlaces que faltaban.";}
 /** Chat intents about the running job: status, pause, resume or cancel; null otherwise. */
 static String parse(String raw){String q=ChatLanguage.normalize(NaturalCoding.polite(raw));if(q.matches("(?:estado|como va|como viene|informe|progreso) (?:del |el )?recorrido(?: de (?:sub ?enlaces|enlaces))?|que leiste del recorrido"))return "status";if(q.matches("(?:pausa|pausar|frena|detene por ahora) (?:el |la )?(?:recorrido|lectura de (?:sub ?enlaces|enlaces))"))return "pause";if(q.matches("(?:segui|sigue|continua|reanuda|retoma)(?: con)? (?:el |la )?(?:recorrido|lectura de (?:sub ?enlaces|enlaces))"))return "resume";if(q.matches("(?:cancela|cancelar|corta|termina|aborta|detene|para) (?:el |la )?(?:recorrido|lectura de (?:sub ?enlaces|enlaces))"))return "cancel";return null;}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String kind=parse(input);if(kind==null)return null;try{return MobileCore.say(c,kind.equals("status")?status(c):kind.equals("pause")?pause(c):kind.equals("resume")?resume(c):cancel(c),"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,"No pude con el recorrido: "+AndroidRepair.summary(e),"aprendizaje_local");}}
}
